create table xxventuri.eba_sales_deal_products (
    id                    number,
    row_version_number    number,
    row_key               varchar2(255 byte),
    deal_id               number not null enable,
    product_id            number not null enable,
    quote_price           number,
    tcv                   number,
    term                  number,
    close_date            date,
    qtr                   varchar2(255 byte),
    deal_prod_probability number,
    deal_prod_description varchar2(4000 byte),
    created_by            varchar2(255 byte),
    created               timestamp(6) with local time zone,
    updated_by            varchar2(255 byte),
    updated               timestamp(6) with local time zone,
    flex_01               varchar2(4000 byte),
    flex_02               varchar2(4000 byte),
    flex_03               varchar2(4000 byte),
    flex_04               varchar2(4000 byte),
    flex_05               varchar2(4000 byte),
    flex_06               varchar2(4000 byte),
    flex_07               varchar2(4000 byte),
    flex_08               varchar2(4000 byte),
    flex_09               varchar2(4000 byte),
    flex_10               varchar2(4000 byte),
    flex_d01              timestamp(6) with local time zone,
    flex_d02              timestamp(6) with local time zone,
    flex_d03              timestamp(6) with local time zone,
    flex_d04              timestamp(6) with local time zone,
    flex_d05              timestamp(6) with local time zone,
    flex_n01              number,
    flex_n02              number,
    flex_n03              number,
    flex_n04              number,
    flex_n05              number,
    flex_n06              number,
    flex_n07              number,
    flex_n08              number,
    flex_n09              number,
    flex_n10              number,
    product_group_id      number,
    product_brand_id      number,
    product_price         number,
    currency_type         varchar2(20 byte),
    quantity              number,
    status                varchar2(10 byte),
    minimum_price         number,
    product_cost          number
);

alter table xxventuri.eba_sales_deal_products add primary key ( id )
    using index enable;


